#!/bin/bash
# Crash gates for the non-bit-exact layer: suites must complete without panics; hash mismatches are expected and not failures here.
while ! grep -q CHAIN_LZ1_DONE /puffertank/experiments/nethack-rng-freedom-20261011/lz1/chain_lz1.log; do sleep 10; done
LIB=/puffertank/experiments/nethack-compact-state-20261008/engines/lz1/build/libnethack.so; G=/puffertank/experiments/nethack-perf-20260917/gates; DAT=/puffertank/experiments/nethack-perf-20260917/dat
for suite in fuzz goldens; do NH_LAZY=1 $G/replay_golden $LIB $DAT /puffertank/experiments/nethack-compact-state-20261008/checks/$suite/*.golden > /puffertank/experiments/nethack-rng-freedom-20261011/lz1/gate_$suite.log 2>&1; echo "GATE2_$suite rc=$? crashes=$(grep -c -i 'panic\|segmentation\|abort\|impossible\|desync' /puffertank/experiments/nethack-rng-freedom-20261011/lz1/gate_$suite.log) mismatch_lines=$(grep -c -i 'mismatch\|differ' /puffertank/experiments/nethack-rng-freedom-20261011/lz1/gate_$suite.log)"; done
NH_LAZY=1 NLE_REPLAY_OPTIONS_APPEND=',!status_updates' $G/replay_golden $LIB $DAT /puffertank/experiments/nethack-compact-state-20261008/checks/goldens/*.golden > /puffertank/experiments/nethack-rng-freedom-20261011/lz1/gate_status.log 2>&1; echo "GATE2_status rc=$? crashes=$(grep -c -i 'panic\|segmentation\|abort\|impossible\|desync' /puffertank/experiments/nethack-rng-freedom-20261011/lz1/gate_status.log)"
for m in interleaved shuffled; do NH_LAZY=1 $G/replay_multi --$m $LIB $DAT /puffertank/experiments/nethack-compact-state-20261008/checks/goldens/*.golden > /puffertank/experiments/nethack-rng-freedom-20261011/lz1/gate_$m.log 2>&1; echo "GATE2_$m rc=$? crashes=$(grep -c -i 'panic\|segmentation\|abort\|impossible\|desync' /puffertank/experiments/nethack-rng-freedom-20261011/lz1/gate_$m.log)"; done
echo "GATES2_DONE $(date -u +%T)"
